// TH18 v1.00a Extra, Boss4 non-spell.
// Source: st07bs.ecl.txt:404-463 (Boss4), :465-490 (Boss4_at),
//         default.ecl.txt:2-14 (BossItem: reward-only, omitted by policy).
// Card frame ~= source frame + 123 (main -> control -> pattern spawn offsets).
// Source slot-0 timeout is 3600 frames; phase budget is 120 buffer + 3600 + 60 tail.

const TIME_LIMIT: int = 3780;
const OPENING_BUFFER: int = 120;

const TH18_ARROWHEAD: int = 544; // source etSprite(12, 14)
const ARROWHEAD_COLOR: int = 14;

// Boss4_at emitter 0/1 constants (radians in source, BAM here).
// D=0.12217305 rad=7deg, E=0.017453292 rad=1deg/frame, F=0.022689281 rad=1.3deg/layer.
const VOLLEY_COUNT: int = 342; // source timeout 3600: fires from t=180 every 10 frames

// Boss4_at EX chain: VELTIME 60 frames (1.2 -> 3.0), then ANGLE_ACCEL 30 frames
// (speed -0.03/frame, angle av/frame).  ANIM's 4*speed birth retreat is handled
// per bullet at fire time so it uses each layer's own initial speed.
xformdef BOSS4_BULLET(acc: fx, av: angle) {
    @60 set_accel(acc); // VELTIME: (3.0 - layer speed)/60, then hold 60 frames
    set_accel(0fx);
    set_ang_vel(av);
    @30 set_accel(-0.03fx); // ANGLE_ACCEL: 30 frames at av/frame, -0.03/frame
    set_accel(0fx);
    set_ang_vel(0deg);
}

// Boss4_at loop.  Source emitter slot 0 / 1 is an independent async context;
// here each call becomes one spawned task with its own fire calls.
async sub emitter(rot: angle, delta: angle, av: angle) {
    // %G = %ANGLE_PLAYER: read once per async context, then rotate by D.
    var g: angle = aim_player();
    var layer_step: int = delta as int;
    for n in 0..VOLLEY_COUNT {
        for q in 0..8 {
            // etSpeed(1.2, 0): layer q speed = 1.2 * (7-q) / 7 (exact 0 at q=7).
            var speed: fx = (1.2fx * ((7 - q) as fx)) / 7fx;
            // etAngle's second arg F is the per-layer rotation.
            var layer_off: angle = (q * layer_step) as angle;
            // etDist(32) along each bullet's own angle, then ANIM -4*initial speed.
            var d: fx = 32fx - 4fx * speed;
            var accel: fx = (3.0fx - speed) / 60; // VELTIME target 3.0 over 60 frames
            for i in 0..3 {
                // mode 5: alpha + pi/N + R(i) + q*F, fixed-direction ring.
                var a: angle = g + 60deg + ((i * 65536) / 3) as angle + layer_off;
                var x: fx = $self_x + d * cos(a);
                var y: fx = $self_y - 24fx + d * sin(a); // etOffset(0, -24)
                _ = fire(TH18_ARROWHEAD, ARROWHEAD_COLOR, x, y, speed, a,
                         BOSS4_BULLET(accel, av), none);
            }
        }
        g = g + rot;
        wait(10);
    }
}

// --- moveRand(60, 4, 1.0) with moveLimit(0, 128, 240, 64) ---
// Recipe from movement.md, retargeted to this limit: inner direction box
// x +/-60, y 112..144; actual position clamp x +/-120, y 96..160.
// Enemy self slots: int0 = next step count; fx0/fx1 = logical unit vector.
sub card_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -120fx { nx = -120fx; }
    if nx > 120fx { nx = 120fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}

sub card_move_rand() {
    // Source signed unit random * pi, represented as unwrapped BAM ints.
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -60fx {
        a = r / 3;
    } else if $self_x > 60fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; } // source normalizes this branch
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
        // Central branch is intentionally not normalized before the y tests.
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +/-pi/2 guard (0.05 rad); nearest BAM boundaries.
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}

sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}

async sub boss_body() {
    // Source Boss4 entry: setInvuln(120), lifeSet(19000); training shell keeps
    // the real enemy invulnerable for the whole card.
    set_invuln(65535);
    // Source Boss() setHurtbox(40)/setHitbox(48): ordinary circle radii 20/24.
    set_hurtbox(20fx);
    set_hitbox(24fx);

    // movePosTime(60, 4, 0, 128): entry is already (0,128) per task contract.
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    wait(120); // source line 443
    // moveLimit(0,128,240,64) is now active (enforced in card_arm_next_step).
    wait(60);  // source lines 445-447
    // Boss4_at(..., 3, 8, ...) called async for emitter 0 and 1.
    spawn emitter(7deg, -1.3deg, 1deg);
    spawn emitter(-7deg, 1.3deg, -1deg);

    // Boss4_1320 loop: moveRand at t=280,440,600,... (every 160 frames).
    // Only the part before the source timeout (3600) is part of this card.
    for cycle in 0..10 {
        wait(100);
        card_move_rand();
        card_wait(60);
        card_wait(100);
        card_move_rand();
        card_wait(60);
    }
    wait(100);
    card_move_rand(); // t=3480
    card_wait(60);    // movement through t=3540; source timeout follows
    loop { wait(1); }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 19000, 0, 0, 0, boss_body);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
